∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}
  [inst_3 : TopologicalSpace β] {x₀ : β},
  ContinuousAt f x₀ → ContinuousAt g x₀ → f x₀ < g x₀ → ∀ᶠ (x : β) in nhds x₀, f x < g x

∀ {α : Type u} {γ : Type w} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {l : Filter γ}
  {f g : γ → α} {y z : α},
  Filter.Tendsto f l (nhds y) → Filter.Tendsto g l (nhds z) → y < z → ∀ᶠ (x : γ) in l, f x < g x
